from fl_dsl import unit, S, q, concept, math, deeper, src

unit('CONTRACT', 'Contracts, Subscriptions, and Fees', ['19 Contracts and Fees'])

FTC_NEG = src('FTC (Free trials, auto-renewals, and subscriptions)', 'https://consumer.ftc.gov/articles/getting-and-out-free-trials-auto-renewals-and-negative-option-subscriptions', 'Free trials and subscriptions often renew automatically and charge a card on file unless canceled; consumers should note renewal dates and how to cancel. Federal and state auto-renewal rules have changed in recent years.')
FTC_WARR = src('FTC (Warranties)', 'https://consumer.ftc.gov/articles/warranties', 'Explains written warranties, implied warranties, and service contracts (often called extended warranties).')
FTC_FEES = src('FTC (Rule on Unfair or Deceptive Fees takes effect)', 'https://www.ftc.gov/news-events/news/press-releases/2025/05/ftc-rule-unfair-or-deceptive-fees-take-effect-may-12-2025', 'A federal rule effective May 12, 2025 requires live-event ticket and short-term lodging sellers to show the total price, including mandatory fees, up front.', eff='2025-05-12')
NJ_DCA = src('New Jersey Division of Consumer Affairs', 'https://www.njconsumeraffairs.gov/', 'New Jersey residents can file consumer complaints, including about contracts and refund policies, with the Division of Consumer Affairs.', jur='New Jersey')
CFPB_BNPL = src('CFPB (Buy now, pay later)', 'https://www.consumerfinance.gov/ask-cfpb/what-is-a-buy-now-pay-later-bnpl-loan-en-2108/', 'Buy now, pay later loans split a purchase into installments; missed payments can bring late fees.')

# ---------------------------------------------------------------- S105
S(105, 'Reading a contract before signing', 'Identify the key terms of a contract and the questions to ask before signing',
  main=[
    q('Jamal is about to sign a gym membership contract. Which part tells him how to end it?', 'The cancellation terms',
      [('The gym\'s logo and address at the top of the page', 'Identifies the business only'), ('The list of classes offered this month', 'Marketing, not a term'), ('The photo on his membership card', 'Not part of the contract terms')],
      intro='A contract is a legally binding agreement. Key parts: the parties, what each promises, the price and fees, the length (term), how it renews, how to cancel, and how disputes are handled. Read every page before signing and keep a copy.',
      fb='Cancellation terms explain how and when the contract can be ended and at what cost.', sub='Key terms', how=True),
    q('The gym contract is $35 a month for 12 months, plus a $49 sign-up fee and a $60 annual fee. What is the first-year cost?', '$529',
      [('$420', 'Counts only the monthly dues'), ('$469', 'Leaves out the annual fee'), ('$480', 'Leaves out the sign-up fee')],
      intro='The full cost of a contract includes monthly charges plus one-time and yearly fees.',
      fb='12 × $35 = $420; $420 + $49 + $60 = $529.', calc=529, sub='Total contract cost'),
    q('A salesperson says, "Don\'t worry about the fine print; you can cancel anytime." The written contract says cancellation costs $150. Which usually controls?', 'The written contract',
      [('The salesperson\'s spoken promise, because it came first', 'Spoken promises are hard to prove'), ('Whatever Jamal remembers later', 'Memory is not evidence'), ('Neither, since gym contracts are not binding', 'They are binding')],
      intro='If a promise matters, get it in writing in the contract. Signed written terms usually control over spoken promises.',
      fb='Signed written terms usually control; ask for promises in writing.', sub='Written vs spoken'),
    q('The contract says disputes go to "binding arbitration." What does that usually mean?', 'A private arbitrator decides instead of a court',
      [('Jamal can sue in any court he chooses', 'Reverses the clause'), ('The gym must refund him automatically', 'Invents a remedy'), ('A judge must approve every monthly bill the gym sends', 'Misreads the clause')],
      intro='An arbitration clause sends disputes to a private arbitrator, often limiting class actions and appeals.',
      fb='Arbitration replaces a court case with a private decision.', sub='Arbitration clauses'),
    q('Jamal is 17. In most states, what is generally true of contracts signed by minors?', 'The minor can often cancel them',
      [('They are stricter than adult contracts', 'Reverses the rule'), ('They can never be signed at all', 'Minors can sign some'), ('Parents automatically owe the money', 'Not automatic')],
      intro='In most states, including New Jersey, the age of majority is 18. Many contracts signed by minors are voidable by the minor, though contracts for necessities can be enforced. Businesses often require a parent to cosign.',
      fb='Minors can usually void many contracts, which is why businesses ask for a parent\'s signature.', sub='Minors and contracts'),
  ],
  back=[
    concept('What makes a contract', 'Reading a contract is easier with its basic parts in mind.', [
      q('A contract is…', 'A legally binding agreement',
        [('A suggestion with no effect', 'Not binding'), ('A store receipt only', 'Too narrow'), ('A promise that only the business must keep', 'Misses that both sides are bound')],
        fb='Contracts are enforceable promises.', sub='Definition'),
      q('The "term" of a contract is…', 'How long it lasts',
        [('The price', 'Separate item'), ('The company name', 'Party'), ('The signature line', 'Not the term')],
        fb='The term is the length of the agreement.', sub='Term'),
      q('12 months at $25 a month is…', '$300',
        [('$37', 'Adds'), ('$250', 'Uses 10 months'), ('$3,000', 'Adds a zero')],
        fb='12 × $25 = $300.', calc=300, sub='Monthly to yearly'),
      q('Why keep a copy of a signed contract?', 'To check the terms later',
        [('Copies are illegal to keep', 'Invents a rule'), ('It cancels the contract', 'Misreads copies'), ('It replaces the need to read it', 'Misunderstands copies')],
        fb='A copy proves what was agreed.', sub='Keeping copies', how=True),
      q('Which should Jamal do before signing?', 'Read every page and ask questions',
        [('Sign quickly to avoid holding up the line', 'Rushing'), ('Read only the first page', 'Misses terms'), ('Let the salesperson summarize it', 'Relies on the other party')],
        fb='Read all terms and ask about anything unclear.', sub='Before signing', how=True),
    ]),
    math('Solve multistep problems with rational numbers', 'Total contract cost adds monthly, one-time, and yearly charges.', 'grade_7', 29),
  ],
  go=[
    deeper('Getting out of a contract', [
      q('Jamal cancels after 5 months of a 12-month gym contract. The fee is $20 for each remaining month. What is the fee?', '$140',
        [('$100', 'Uses the 5 months used'), ('$240', 'Uses all 12 months'), ('$20', 'Charges one month')],
        intro='Early termination fees are often figured from the months left on the term.',
        fb='12 − 5 = 7 months left; 7 × $20 = $140.', calc=140, sub='Early termination'),
      q('How should Jamal cancel to have proof?', 'In writing, keeping a dated copy',
        [('By telling a trainer in the hallway', 'No record'), ('By just stopping payments', 'Can lead to collections'), ('By deleting the gym app', 'Not cancellation')],
        fb='Written cancellation creates a record.', sub='Proof of canceling', how=True),
      q('After canceling, the gym keeps charging Jamal\'s debit card. What should he do first?', 'Contact his bank and dispute the charges',
        [('Ignore it and hope it stops', 'Lets charges continue'), ('Stop opening his bank statements until it ends', 'Avoids the problem'), ('Pay extra to make them stop', 'Rewards the error')],
        intro='Banks can stop recurring payments and investigate unauthorized charges. Keep the cancellation proof.',
        fb='The bank can block and investigate charges; New Jersey residents can also complain to the Division of Consumer Affairs.', sub='Unwanted charges', how=True),
      q('A contract says it "automatically renews for another 12 months unless canceled 30 days before the end." The term ends June 30. By about when must Jamal cancel?', 'By May 31',
        [('By June 30', 'Ignores the notice period'), ('By July 30', 'After the term'), ('Any time in July', 'After renewal')],
        fb='30 days before June 30 is May 31.', sub='Notice periods'),
      q('Which choice best protects Jamal before signing a long contract?', 'Asking for a month-to-month option',
        [('Signing two contracts at once', 'Doubles commitment'), ('Prepaying three years', 'Hard to recover'), ('Skipping the cancellation section to save time', 'Misses key terms')],
        fb='Shorter commitments are easier to leave.', sub='Flexibility'),
    ]),
  ],
  nat=('Spending', 'Identify the rights and responsibilities in contracts and evaluate their costs before signing'), nj=['CDM', 'FP'],
  sources=[NJ_DCA], extra=['Reading cancellation terms', 'Canceling in writing'])

# ---------------------------------------------------------------- S106
S(106, 'Subscriptions, free trials, and phone plans', 'Find the true cost of subscriptions and compare service plans',
  main=[
    q('Jamal has three streaming services at $15.99 each per month. What do they cost in a year?', '$575.64',
      [('$191.88', 'Counts one service for a year'), ('$47.97', 'Gives one month for all three'), ('$479.70', 'Uses 10 months')],
      intro='Small monthly charges add up. Yearly cost = monthly cost × 12.',
      fb='3 × $15.99 = $47.97; × 12 = $575.64.', calc=575.64, sub='Subscription cost'),
    q('A free 7-day trial requires a card and converts to $12.99 a month. Jamal wants only the trial. What should he do?', 'Set a reminder to cancel before day 7',
      [('Assume trials end on their own', 'Most auto-convert'), ('Give a fake card number', 'Dishonest'), ('Sign up twice to get a longer free trial', 'Breaks terms')],
      intro='Many free trials automatically become paid subscriptions. Note the end date and how to cancel when you sign up.',
      fb='Cancel before the trial ends to avoid charges.', sub='Free trials', how=True),
    q('Plan A: $45 a month, unlimited data. Plan B: $25 a month plus $10 per GB. At how many GB a month do the plans cost the same?', '2 GB',
      [('4.5 GB', 'Divides $45 by $10'), ('20 GB', 'Uses the $20 difference'), ('7 GB', 'Adds the plans')],
      intro='Set the costs equal: 25 + 10g = 45. Below that amount, Plan B is cheaper; above it, Plan A is.',
      fb='10g = 20, so g = 2 GB.', calc=2, sub='Comparing plans'),
    q('Plan A: $45 a month, unlimited data. Plan B: $25 a month plus $10 per GB. Jamal uses about 6 GB a month. Which is cheaper, and by how much?', 'Plan A, by $40 a month',
      [('Plan B, by $40 a month', 'Reverses the comparison'), ('Plan A, by $20 a month', 'Compares base prices'), ('Plan B, by $20 a month', 'Ignores data charges')],
      fb='Plan B: $25 + 6 × $10 = $85. Plan A: $45. A is $40 less.', calc=40, pick=0, shared=True, sub='Choosing a plan'),
    q('A phone sells for $0 down and $33.34 a month for 36 months on a plan. What is the phone\'s total cost?', '$1,200.24',
      [('$33.34', 'One payment'), ('$400.08', 'Uses 12 months'), ('$0', 'Believes "$0 down" means free')],
      fb='36 × $33.34 = $1,200.24.', calc=1200.24, sub='Device payments'),
  ],
  back=[
    concept('Recurring charges', 'Subscriptions are recurring charges; comparing plans needs total cost.', [
      q('A recurring charge is one that…', 'Repeats automatically on a schedule',
        [('Happens only once', 'Reverses the meaning'), ('Is always free', 'Misreads recurring'), ('Ends automatically after a year', 'Assumes subscriptions stop')],
        fb='Recurring charges repeat until canceled.', sub='Recurring charges'),
      q('$9.99 a month for a year is…', '$119.88',
        [('$99.90', 'Uses 10 months'), ('$21.99', 'Adds 12'), ('$9.99', 'One month')],
        fb='$9.99 × 12 = $119.88.', calc=119.88, sub='Yearly cost'),
      q('25 + 10 × 3 = ?', '55',
        [('105', 'Adds first'), ('38', 'Adds all'), ('65', 'Multiplies wrong')],
        fb='10 × 3 = 30; 25 + 30 = 55.', calc=55, sub='Order of operations'),
      q('Which tool helps find forgotten subscriptions?', 'Reviewing bank and card statements',
        [('Deleting old emails without reading them', 'Hides information'), ('Checking the app store\'s top charts', 'Not tied to her accounts'), ('Asking friends what they subscribe to', 'Not tied to her accounts')],
        fb='Statements list every recurring charge.', sub='Finding subscriptions', how=True),
      q('A "$0 down" phone deal means…', 'The cost is spread into monthly payments',
        [('The phone is free', 'Misreads $0 down'), ('No contract is involved', 'Often an agreement'), ('Taxes are waived', 'Invents a benefit')],
        fb='"$0 down" spreads the price over months.', sub='$0 down'),
    ]),
    math('Write and solve systems of linear equations for real-world problems', 'Comparing two plans finds where two costs are equal.', 'grade_8', 22),
  ],
  go=[
    deeper('Auditing subscriptions', [
      q('Jamal\'s audit finds subscriptions of $15.99, $10.99, $6.99, and $4.99. He cancels the two he rarely uses: $10.99 and $4.99. How much does he save a year?', '$191.76',
        [('$15.98', 'Gives one month'), ('$467.52', 'Gives the total of all four for a year'), ('$275.76', 'Gives what he keeps')],
        fb='$10.99 + $4.99 = $15.98; × 12 = $191.76.', calc=191.76, sub='Subscription audit'),
      q('A service offers $99 a year or $9.99 a month. How much does the yearly plan save?', '$20.88',
        [('$0.99', 'Compares one month'), ('$89.01', 'Subtracts monthly from yearly'), ('$119.88', 'Gives the monthly plan total')],
        fb='$9.99 × 12 = $119.88; $119.88 − $99 = $20.88.', calc=20.88, sub='Annual vs monthly'),
      q('When is a yearly plan a poor choice?', 'When you may stop using it soon',
        [('When you use it every day', 'Good fit'), ('When it is cheaper per month overall', 'Good fit'), ('When prices are rising', 'Can be good')],
        fb='Prepaying for a year wastes money if you quit early.', sub='Commitment risk'),
      q('Jamal shares a family plan for $60 a month with 3 other people, split equally. What is his share per year?', '$180',
        [('$720', 'Gives the whole plan'), ('$15', 'Gives one month'), ('$240', 'Splits among 3')],
        fb='$60 ÷ 4 = $15; × 12 = $180.', calc=180, sub='Sharing plans'),
      q('A price-increase email says a subscription will rise from $12.99 to $15.99. What is the yearly increase?', '$36',
        [('$3', 'One month'), ('$191.88', 'Gives the new yearly cost'), ('$155.88', 'Gives the old yearly cost')],
        fb='$3 × 12 = $36.', calc=36, sub='Price increases'),
    ]),
  ],
  nat=('Spending', 'Calculate the cost of subscriptions and service plans and compare options'), nj=['PB', 'FP'],
  status='time_sensitive', sources=[FTC_NEG], extra=['Auditing subscriptions', 'Canceling a free trial'])

# ---------------------------------------------------------------- S107
S(107, 'Fees, warranties, and the true price', 'Find the total price with fees and evaluate warranties and buy now, pay later plans',
  main=[
    q('A concert ticket costs $60, plus an 18% service fee and a $5 facility fee. What is the total?', '$75.80',
      [('$70.80', 'Leaves out the facility fee'), ('$83.00', 'Adds $18 instead of 18%'), ('$65.00', 'Leaves out the service fee')],
      intro='Many purchases add fees: percent fees (a percent of the price) and flat fees (a set dollar amount). Compare total prices, not base prices. Federal rules now require ticket and hotel sellers to show the total price with mandatory fees up front.',
      fb='$60 × 0.18 = $10.80; $60 + $10.80 + $5 = $75.80.', calc=75.80, sub='Percent and flat fees', eff='FTC fee rule effective 2025-05-12'),
    q('A $600 laptop is split into 4 buy-now-pay-later payments. Jamal misses one and pays a $7 late fee. What does the laptop cost him?', '$607',
      [('$600', 'Ignores the fee'), ('$150', 'Gives one payment'), ('$628', 'Charges the fee on every payment')],
      intro='Buy now, pay later (BNPL) splits a purchase into installments, often with no interest if paid on time. Late fees and overlapping plans can make it costly.',
      fb='$600 + $7 = $607.', calc=607, sub='Buy now, pay later'),
    q('What does a manufacturer\'s one-year warranty on a laptop usually cover?', 'Defects in parts or work',
      [('Damage from dropping it in a pool', 'Accidents are usually excluded'), ('Any problem for the life of the laptop', 'Limited period'), ('Theft of the laptop', 'Insurance covers theft')],
      intro='A warranty is a promise about a product\'s quality. A manufacturer\'s warranty usually covers defects for a set period. An "extended warranty" is a separate service contract you pay for.',
      fb='Warranties cover defects, not accidents or theft.', sub='Warranties'),
    q('An extended warranty for a $300 headphone set costs $60. What percent of the price is it?', '20%',
      [('5%', 'Divides $300 by $60 and treats it as a percent'), ('60%', 'Uses the dollars as a percent'), ('17%', 'Divides by $360, the price plus the warranty')],
      fb='$60 ÷ $300 = 20%.', calc=20, sub='Warranty cost'),
    q('Two hotels list $120 and $135 a night. The first adds a $30 nightly "resort fee"; the second has none. Which costs less per night?', 'The second, by $15',
      [('The first, by $15', 'Compares base prices'), ('The second, by $45', 'Adds the differences'), ('The first, by $30', 'Uses only the fee')],
      fb='First: $150. Second: $135. The second is $15 less.', calc=15, pick=0, shared=True, sub='Comparing total prices'),
  ],
  back=[
    concept('Percent fees and flat fees', 'Total price adds a percent fee and a flat fee to the base price.', [
      q('10% of $40 is…', '$4',
        [('$40.10', 'Adds 10 cents'), ('$0.40', 'Uses 1%'), ('$14', 'Adds 10')],
        fb='$40 × 0.10 = $4.', calc=4, sub='Percent fee'),
      q('A $50 item has a $3 flat fee. Total?', '$53',
        [('$51.50', 'Treats $3 as 3%'), ('$47', 'Subtracts'), ('$150', 'Multiplies')],
        fb='$50 + $3 = $53.', calc=53, sub='Flat fee'),
      q('What is a flat fee?', 'A set dollar amount',
        [('A percent of the price', 'Percent fee'), ('A fee that rises with the price', 'Describes a percent fee'), ('A fee charged only on refunds', 'Misreads the term')],
        fb='Flat fees do not change with price.', sub='Vocabulary'),
      q('$80 with a 5% fee and a $2 flat fee totals…', '$86',
        [('$87', 'Uses $5 as the percent fee'), ('$84', 'Leaves out the flat fee'), ('$82', 'Leaves out the percent fee')],
        fb='$80 × 0.05 = $4; $80 + $4 + $2 = $86.', calc=86, sub='Both fees'),
      q('A warranty covers…', 'Defects for a set time',
        [('Anything that ever happens', 'Overstates'), ('Accidental drops and spills', 'Confuses with insurance'), ('Theft of the item', 'Confuses with insurance')],
        fb='Warranties cover defects for a period.', sub='Warranty basics'),
    ]),
    math('Find a percent fee and the total with the fee', 'Fees are often a percent of the price added to the total.', 'grade_7', 65),
  ],
  go=[
    deeper('Hidden costs', [
      q('A debit card transaction at an out-of-network ATM costs a $3 bank fee and a $3.50 owner fee. Jamal does this 4 times a month. What are his yearly ATM fees?', '$312',
        [('$26', 'Gives one month'), ('$78', 'Counts one withdrawal a month'), ('$144', 'Uses only the bank fee')],
        fb='$6.50 × 4 = $26; × 12 = $312.', calc=312, sub='Fees add up'),
      q('A payment app charges 1.75% to transfer money instantly. On $400, what is the fee?', '$7',
        [('$70', 'Uses 17.5%'), ('$0.70', 'Uses 0.175%'), ('$1.75', 'Uses the rate as dollars')],
        fb='$400 × 0.0175 = $7.', calc=7, sub='Instant transfer fees'),
      q('A $120 jacket is "final sale." What does that usually mean?', 'It cannot be returned',
        [('It can be exchanged but not refunded, by law', 'Invents a rule'), ('It has a lifetime warranty', 'Confuses sales terms with warranties'), ('It must be returned within 30 days', 'Reverses')],
        intro='Stores set return policies; "final sale" usually means no returns. In New Jersey, stores generally must post their refund policy.',
        fb='Final sale items usually cannot be returned.', sub='Return policies'),
      q('Jamal has 3 BNPL plans with payments of $50, $75, and $40 due the same week. How much must he have ready?', '$165',
        [('$125', 'Leaves out the $40'), ('$115', 'Leaves out the $50'), ('$90', 'Leaves out the $75')],
        fb='$50 + $75 + $40 = $165.', calc=165, sub='Stacked BNPL'),
      q('Which question best tests whether an extended warranty is worth it?', 'Could I afford the repair myself?',
        [('Is the warranty price on sale today?', 'Focuses on the discount, not the value'), ('Does it cover more years than the product will last?', 'Longer is not always better value'), ('Do my friends own one?', 'Follows others')],
        fb='If you can afford repairs, a warranty is often not worth its cost.', sub='Judging warranties'),
    ]),
  ],
  nat=('Spending', 'Calculate total prices including fees and evaluate warranties and installment plans'), nj=['CDM', 'PB'],
  status='time_sensitive', sources=[FTC_FEES, FTC_WARR, CFPB_BNPL], extra=['Comparing total prices with fees', 'Deciding on extended warranties'])
